package oracle;
import java.util.*;import java.io.*;import java.nio.file.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;import core.game.node.entity.npc.NPC;import core.game.world.map.Location;
public class Support {
 static Map input;static List<Object>events;public static List<NPC>npcs;static Map<String,Integer>calls;
 public static class Failure extends RuntimeException{}
 public static void emit(String phase,Object...args){List row=new ArrayList();row.add(phase);row.addAll(Arrays.asList(args));events.add(row);int at=calls.merge(phase,1,Integer::sum);Object fail=((Map)input.getOrDefault("failures",Collections.emptyMap())).get(phase);if(fail!=null&&at==((Number)fail).intValue())throw new Failure();}
 public static Object coord(Location l){return Arrays.asList(l.getX(),l.getY(),l.getZ());}
 public static boolean booth(NPC n){emit("booth",n.slot);return((List)input.getOrDefault("booths",Collections.emptyList())).contains((long)n.id);}
 public static void main(String[]args)throws Exception{Path dir=Paths.get(args[0]);Files.createDirectories(dir);try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);events=new ArrayList<>();npcs=new ArrayList<>();calls=new HashMap<>();String text=(String)input.get("text");if(text==null)text=Files.readString(Paths.get(args[1]));Files.writeString(dir.resolve("npc_spawns.json"),text);core.ServerConstants.CONFIG_PATH=dir.toString()+File.separator;String error=null;try{new core.game.system.config.NPCSpawner().load();}catch(Throwable e){error=e instanceof NumberFormatException?"Number":e instanceof IndexOutOfBoundsException?"Index":e instanceof NullPointerException?"Null":e instanceof ClassCastException?"Type":e instanceof org.json.simple.parser.ParseException?"Json":e instanceof Failure?"Binding":e.getClass().getSimpleName();}List rows=new ArrayList();for(NPC n:npcs)rows.add(Arrays.asList(n.id,coord(n.location),n.walks,n.getDirection().ordinal(),n.attributes,n.initialized));Map out=new TreeMap();out.put("npcs",rows);out.put("events",events);out.put("error",error);input.put("expected",out);System.out.println(JSONValue.toJSONString(input));}}}
}
